package cmd

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// gzenvMarshal encodes an object into the gzenv format: JSON, zlib
// compressed, URL-safe base64 encoded.
func gzenvMarshal(obj interface{}) string {
	jsonData, err := json.Marshal(obj)
	if err != nil {
		panic(fmt.Errorf("marshal(): %w", err))
	}

	zlibData := bytes.NewBuffer([]byte{})
	w := zlib.NewWriter(zlibData)
	_, _ = w.Write(jsonData)
	_ = w.Close()

	return base64.URLEncoding.EncodeToString(zlibData.Bytes())
}

// gzenvUnmarshal is the inverse of gzenvMarshal.
func gzenvUnmarshal(gzenv string, obj interface{}) error {
	gzenv = strings.TrimSpace(gzenv)

	data, err := base64.URLEncoding.DecodeString(gzenv)
	if err != nil {
		return fmt.Errorf("unmarshal() base64 decoding: %w", err)
	}

	r, err := zlib.NewReader(bytes.NewReader(data))
	if err != nil {
		return fmt.Errorf("unmarshal() zlib opening: %w", err)
	}

	buf := bytes.NewBuffer([]byte{})
	_, err = io.Copy(buf, r)
	if err != nil {
		return fmt.Errorf("unmarshal() zlib reading: %w", err)
	}
	_ = r.Close()

	err = json.Unmarshal(buf.Bytes(), &obj)
	if err != nil {
		return fmt.Errorf("unmarshal() json parsing: %w", err)
	}

	return nil
}
EOF
