package cmd

import (
	"fmt"
	"log"
	"os"
)

const (
	defaultLogFormat = "direnv: %s"
	errorColor       = "\033[31m"
	clearColor       = "\033[0m"
)

var debugging bool
var logger = log.New(os.Stderr, "", 0)
var debugLogger *log.Logger

func setupLogging(env Env) {
	if debug := env[DIRENV_DEBUG]; debug == "1" {
		debugging = true
		debugLogger = log.New(os.Stderr, "direnv: ", log.Ltime|log.Lshortfile)
	}
}

func logError(c *Config, msg string, a ...interface{}) {
	var format string
	if c == nil || c.LogColor {
		format = errorColor + defaultLogFormat + clearColor + "\n"
	} else {
		format = defaultLogFormat + "\n"
	}
	msg = fmt.Sprintf(format, msg)
	logger.Printf(msg, a...)
}

func logStatus(c *Config, msg string, a ...interface{}) {
	if c == nil {
		return
	}
	format := c.LogFormat
	if format == "" || format == "-" {
		return
	}
	if c.LogFilter != nil && !c.LogFilter.MatchString(msg) {
		return
	}
	if c.LogColor {
		format = clearColor + format
	}
	msg = fmt.Sprintf(format+"\n", msg)
	logger.Printf(msg, a...)
}

func logDebug(msg string, a ...interface{}) {
	if !debugging {
		return
	}
	defer log.SetFlags(log.Flags())
	msg = fmt.Sprintf(msg, a...)
	_ = debugLogger.Output(2, msg)
}
EOF
echo ok

