package cmd

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

// Config represents the direnv configuration and state.
type Config struct {
	Env             Env
	WorkDir         string // Current directory
	ConfigDir       string
	CacheDir        string
	DataDir         string
	SelfPath        string
	BashPath        string
	RCFile          string
	TomlPath        string
	DisableStdin    bool
	StrictEnv       bool
	LoadDotenv      bool
	LogColor        bool
	LogFormat       string
	LogFilter       *regexp.Regexp
	HideEnvDiff     bool
	WarnTimeout     time.Duration
	WhitelistPrefix []string
	WhitelistExact  map[string]bool
}

type tomlDuration struct {
	time.Duration
}

func (d *tomlDuration) UnmarshalText(text []byte) error {
	var err error
	d.Duration, err = time.ParseDuration(string(text))
	return err
}

type tomlConfig struct {
	*tomlGlobal          // For backward-compatibility
	Global      *tomlGlobal  `toml:"global"`
	Whitelist   tomlWhitelist `toml:"whitelist"`
}

type tomlGlobal struct {
	BashPath     string        `toml:"bash_path"`
	DisableStdin bool          `toml:"disable_stdin"`
	StrictEnv    bool          `toml:"strict_env"`
	SkipDotenv   bool          `toml:"skip_dotenv"` // deprecated, use load_dotenv
	LoadDotenv   bool          `toml:"load_dotenv"`
	WarnTimeout  *tomlDuration `toml:"warn_timeout"`
	HideEnvDiff  bool          `toml:"hide_env_diff"`
	LogFormat    string        `toml:"log_format"`
	LogFilter    string        `toml:"log_filter"`
}

type tomlWhitelist struct {
	Prefix []string
	Exact  []string
}

// Expand a path string prefixed with ~/ to the current user's home directory.
// Example: if current user is user1 with home directory in /home/user1, then
// ~/project -> /home/user1/project
// It's useful to allow paths with ~/ in the config.
func expandTildePath(path string, env Env) string {
	if strings.HasPrefix(path, "~/") {
		if homeDir := env["HOME"]; homeDir != "" {
			path = filepath.Join(homeDir, path[2:])
		}
	}
	return path
}

func xdgDir(env Env, xdgVar, homeSuffix string) string {
	if dir := env[xdgVar]; dir != "" {
		return filepath.Join(dir, "direnv")
	}
	if home := env["HOME"]; home != "" {
		return filepath.Join(home, homeSuffix, "direnv")
	}
	return ""
}

// LoadConfig opens up the direnv configuration from the Env.
func LoadConfig(env Env) (config *Config, err error) {
	config = &Config{
		Env: env,
	}

	config.ConfigDir = env[DIRENV_CONFIG]
	if config.ConfigDir == "" {
		config.ConfigDir = xdgDir(env, "XDG_CONFIG_HOME", ".config")
	}
	if config.ConfigDir == "" {
		err = fmt.Errorf("couldn't find a configuration directory for direnv")
		return
	}

	var exePath string
	if exePath, err = os.Executable(); err != nil {
		err = fmt.Errorf("LoadConfig() os.Executable() failed: %w", err)
		return
	}
	// Fix for mingsys
	exePath = strings.Replace(exePath, "\\", "/", -1)
	config.SelfPath = exePath

	// Default Logging settings
	config.LogColor = true

	if config.WorkDir, err = os.Getwd(); err != nil {
		// Happens when the current directory has been removed. Keep going
		// with a partial configuration.
		config.WorkDir = ""
		err = nil
		return
	}

	config.LogFormat = defaultLogFormat

	// Default Warn Timeout
	config.WarnTimeout = 5 * time.Second

	config.RCFile = env[DIRENV_FILE]

	config.WhitelistPrefix = make([]string, 0)
	config.WhitelistExact = make(map[string]bool)

	// Load the TOML config
	config.TomlPath = filepath.Join(config.ConfigDir, "direnv.toml")
	if _, statErr := os.Stat(config.TomlPath); statErr != nil {
		config.TomlPath = filepath.Join(config.ConfigDir, "config.toml")
		if _, statErr := os.Stat(config.TomlPath); statErr != nil {
			config.TomlPath = ""
		}
	}

	if config.TomlPath != "" {
		// Declare global once and then share it between the top-level and
		// the "global" key so that both configuration styles are supported.
		var tomlConf tomlConfig
		if err = tomlDecodeFile(config.TomlPath, &tomlConf); err != nil {
			err = fmt.Errorf("LoadConfig() failed to parse %s: %w", config.TomlPath, err)
			return
		}

		// Logging is now done by the configuration file
		config.LogColor = false

		global := tomlConf.Global
		if global == nil {
			global = tomlConf.tomlGlobal
		}
		if global == nil {
			global = &tomlGlobal{}
		}

		for _, path := range tomlConf.Whitelist.Prefix {
			config.WhitelistPrefix = append(config.WhitelistPrefix, expandTildePath(path, env))
		}

		for _, path := range tomlConf.Whitelist.Exact {
			if !(strings.HasSuffix(path, "/.envrc") || strings.HasSuffix(path, "/.env")) {
				path = filepath.Join(path, ".envrc")
			}

			config.WhitelistExact[expandTildePath(path, env)] = true
		}

		if global.SkipDotenv {
			logError(config, "skip_dotenv has been inverted to load_dotenv.")
		}

		config.HideEnvDiff = global.HideEnvDiff
		if global.LogFormat != "" {
			config.LogFormat = global.LogFormat
		}
		if global.LogFilter != "" {
			if config.LogFilter, err = regexp.Compile(global.LogFilter); err != nil {
				err = fmt.Errorf("error in log filter: %w", err)
				return
			}
		}
		config.BashPath = global.BashPath
		config.DisableStdin = global.DisableStdin
		config.LoadDotenv = global.LoadDotenv
		config.StrictEnv = global.StrictEnv
		if global.WarnTimeout != nil {
			config.WarnTimeout = global.WarnTimeout.Duration
		}
	}

	if timeout, ok := env[DIRENV_WARN_TIMEOUT]; ok {
		if config.WarnTimeout, err = time.ParseDuration(timeout); err != nil {
			logError(config, "invalid DIRENV_WARN_TIMEOUT: %v", err)
			config.WarnTimeout = 5 * time.Second
			err = nil
		}
	}

	if config.BashPath == "" {
		if env[DIRENV_BASH] != "" {
			config.BashPath = env[DIRENV_BASH]
		} else if config.BashPath, err = exec.LookPath("bash"); err != nil {
			err = fmt.Errorf("can't find bash: %w", err)
			return
		}
	}

	if config.CacheDir = xdgDir(env, "XDG_CACHE_HOME", ".cache"); config.CacheDir == "" {
		err = fmt.Errorf("couldn't find a cache directory for direnv")
		return
	}

	if config.DataDir = xdgDir(env, "XDG_DATA_HOME", ".local/share"); config.DataDir == "" {
		err = fmt.Errorf("couldn't find a data directory for direnv")
		return
	}

	return
}

// AllowDir is the folder where all the "allow" files are stored.
func (config *Config) AllowDir() string {
	return filepath.Join(config.DataDir, "allow")
}

// DenyDir is the folder where all the "deny" files are stored.
func (config *Config) DenyDir() string {
	return filepath.Join(config.DataDir, "deny")
}

// AllowedRequiredDir is the folder where the hashes of approved required
// files are stored.
func (config *Config) AllowedRequiredDir() string {
	return filepath.Join(config.DataDir, "allowed-required")
}

// LoadedRC returns a RC file if any has been loaded
func (config *Config) LoadedRC() *RC {
	if config.RCFile == "" {
		logDebug("RCFile is blank - loadedRC is nil")
		return nil
	}
	rcPath := config.RCFile

	timesString := config.Env[DIRENV_WATCHES]

	rc, err := RCFromEnv(rcPath, timesString, config)
	if err != nil {
		logDebug("RCFromEnv error: %v", err)
		return nil
	}
	return rc
}

// FindRC looks for a RC file in the config environment
func (config *Config) FindRC() (*RC, error) {
	return FindRC(config.WorkDir, config)
}

// EnvFromRC loads an RC from a specified path and returns the new environment
func (config *Config) EnvFromRC(path string, previousEnv Env) (Env, error) {
	rc, err := RCFromPath(path, config)
	if err != nil {
		return nil, err
	}
	return rc.Load(previousEnv)
}

// Revert undoes the recorded changes (if any) to the supplied environment,
// returning a new environment
func (config *Config) Revert(env Env) (Env, error) {
	if config.Env[DIRENV_DIFF] == "" {
		return env.Copy(), nil
	}
	diff, err := LoadEnvDiff(config.Env[DIRENV_DIFF])
	if err == nil {
		return diff.Reverse().Patch(env), nil
	}
	return nil, err
}
EOF
echo ok"}

