package cmd

import (
	"fmt"
	"os"
	"strings"
)

type action interface {
	Call(currentEnv Env, args []string, config *Config) error
}

type actionSimple func(env Env, args []string) error

func (fn actionSimple) Call(env Env, args []string, _ *Config) error {
	return fn(env, args)
}

type actionWithConfig func(env Env, args []string, config *Config) error

func (fn actionWithConfig) Call(env Env, args []string, config *Config) error {
	var err error
	if config == nil {
		config, err = LoadConfig(env)
		if err != nil {
			return err
		}
	}
	return fn(env, args, config)
}

// Cmd represents a command
type Cmd struct {
	Name    string
	Desc    string
	Args    []string
	Aliases []string
	Private bool
	Action  action
}

// CmdList contains the list of all direnv sub-commands
var CmdList []*Cmd

func init() {
	CmdList = []*Cmd{
		cmdAllow,
		cmdApplyDump,
		cmdShowDump,
		cmdCheckRequired,
		cmdDeny,
		cmdDotEnv,
		cmdDump,
		cmdEdit,
		cmdExec,
		cmdExport,
		cmdFetchURL,
		cmdHelp,
		cmdHook,
		cmdPrune,
		cmdReload,
		cmdStatus,
		cmdStdlib,
		cmdVersion,
		cmdWatch,
		cmdWatchDir,
		cmdWatchList,
		cmdWatchPrint,
		cmdCurrent,
		cmdLog,
	}
}

func cmdWithWarnTimeout(fn action) action {
	return fn
}

// CommandsDispatch is called by the main() function to dispatch to a
// sub-command
func CommandsDispatch(env Env, args []string) error {
	var command *Cmd
	var commandName string
	var commandPrefix string
	var commandArgs []string

	if len(args) < 2 {
		commandName = "help"
		commandPrefix = args[0]
		commandArgs = []string{}
	} else {
		commandName = args[1]
		commandPrefix = args[0]
		commandArgs = args[1:]
	}

	for _, cmd := range CmdList {
		if cmd.Name == commandName {
			command = cmd
			break
		}

		for _, alias := range cmd.Aliases {
			if alias == commandName {
				command = cmd
				break
			}
		}
		if command != nil {
			break
		}
	}

	if command == nil {
		return fmt.Errorf("command \"%s %s\" not found", commandPrefix, commandName)
	}

	if len(commandArgs) == 0 {
		commandArgs = []string{commandName}
	}

	return command.Action.Call(env, commandArgs, nil)
}

// Main is the main entrypoint to direnv
func Main(environ []string, args []string) int {
	env := envFromList(environ)
	setupLogging(env)

	err := CommandsDispatch(env, args)
	if err != nil {
		os.Stderr.WriteString(errorColor + "direnv: error " + err.Error() + clearColor + "\n")
		return 1
	}
	return 0
}

func joinShells() string {
	names := make([]string, 0, len(supportedShellList))
	for name := range supportedShellList {
		names = append(names, name)
	}
	return "[" + strings.Join(names, ", ") + "]"
}
