)

// dotenvLine is the regexp matching a single statement of a .env file
const dotenvLine = `
\A
\s*
(?:|#.*|          # comment line
(?:export\s+)?    # optional export
([\w\.]+)         # key
(?:\s*=\s*|:\s+?) # separator
(                 # optional value begin
  '(?:\'|[^'])*'  #   single quoted value
  |               #   or
  "(?:\"|[^"])*"  #   double quoted value
  |               #   or
  [^\s\#\n]+      #   unquoted value
)?                # value end
\s*
(?:\#.*)?         # optional comment
)
\z
`

var dotenvLinesRe = regexp.MustCompile("[\\r\\n]+")
var dotenvLineRe = regexp.MustCompile(
	regexp.MustCompile("\\s+").ReplaceAllLiteralString(
		regexp.MustCompile("\\s+# .*").ReplaceAllLiteralString(dotenvLine, ""), ""))

// matches the beginning of a quoted value that continues on the next lines
var dotenvMultilineStartRe = regexp.MustCompile(`\A[^=]+[=:]\s*(?:"[^"]*|'[^']*)\z`)

var dotenvEscRe = regexp.MustCompile("\\\\([^$])")

// dotenvParse reads a string in the .env format and returns a map of the
// extracted key=values.
func dotenvParse(data string, env Env) (Env, error) {
	var dotenv = make(Env)

	lines := dotenvLinesRe.Split(data, -1)
	for i := 0; i < len(lines); i++ {
		line := lines[i]

		if !dotenvLineRe.MatchString(line) {
			m := dotenvMultilineStartRe.FindStringSubmatch(line)
			if m == nil {
				return nil, fmt.Errorf("invalid line: %s", line)
			}
			quote := multilineQuote(line)
			closed := false
			for i+1 < len(lines) {
				i++
				line += "\n" + lines[i]
				if strings.HasSuffix(strings.TrimRight(lines[i], " \t\f\v"), quote) {
					closed = true
					break
				}
			}
			if !closed {
				return nil, fmt.Errorf("unclosed quoted value in .env file")
			}
		}

		match := dotenvLineRe.FindStringSubmatch(line)
		// commented or empty line
		if len(match) == 0 {
			continue
		}
		if len(match[1]) == 0 {
			continue
		}

		key := match[1]
		value := match[2]

		dotenv[key] = dotenvParseValue(value, dotenv, env)
	}

	return dotenv, nil
}

func multilineQuote(line string) string {
	idx := strings.IndexAny(line, "=:")
	rest := strings.TrimLeft(line[idx+1:], " \t\f\v")
	return rest[0:1]
}

func dotenvParseValue(value string, dotenv Env, env Env) string {
	if len(value) <= 1 {
		return value
	}

	singleQuoted := false

	if value[0:1] == "'" && value[len(value)-1:] == "'" {
		// single-quoted string, do not expand
		singleQuoted = true
		value = value[1 : len(value)-1]
	} else if value[0:1] == `"` && value[len(value)-1:] == `"` {
		value = value[1 : len(value)-1]
		value = dotenvExpandNewLines(value)
		value = dotenvUnescapeCharacters(value)
	}

	if !singleQuoted {
		value = dotenvExpandEnv(value, dotenv, env)
	}

	return value
}

func dotenvUnescapeCharacters(value string) string {
	return dotenvEscRe.ReplaceAllString(value, "$1")
}

func dotenvExpandNewLines(value string) string {
	value = strings.Replace(value, "\\n", "\n", -1)
	value = strings.Replace(value, "\\r", "\r", -1)
	return value
}

func dotenvExpandEnv(value string, dotenv Env, env Env) string {
	expander := func(value string) string {
		envKey, defaultValue, hasDefault := dotenvSplitKeyAndDefault(value, ":-")
		expanded, found := dotenv[envKey]
		if found {
			return expanded
		}
		return dotenvGetFromEnvOrDefault(envKey, defaultValue, hasDefault, env)
	}

	return os.Expand(value, expander)
}

func dotenvSplitKeyAndDefault(value string, sep string) (string, string, bool) {
	var i = strings.Index(value, sep)

	if i == -1 {
		return value, "", false
	}
	return value[0:i], value[i+len(sep):], true
}

func dotenvGetFromEnvOrDefault(envKey string, defaultValue string, hasDefault bool, env Env) string {
	var envValue = env[envKey]

	if envValue == "" && hasDefault {
		return defaultValue
	}

	return envValue
}

// dotenvEnvFor returns the environment used to expand the variables of the
// given dotenv file: the PWD is set to the directory of the file.
func dotenvEnvFor(path string, env Env) Env {
	newEnv := env.Copy()
	if dir, err := filepath.Abs(filepath.Dir(path)); err == nil {
		newEnv["PWD"] = dir
	}
	return newEnv
}
