package cmd

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// cmdWatch is `direnv watch SHELL [PATH...]`
var cmdWatch = &Cmd{
	Name:    "watch",
	Desc:    "Adds a path to the list that direnv watches for changes",
	Args:    []string{"SHELL", "PATH..."},
	Private: true,
	Action:  actionSimple(cmdWatchAction),
}

func cmdWatchAction(env Env, args []string) (err error) {
	var shellName string

	if len(args) < 2 {
		return fmt.Errorf("a path is required to add to the list of watches")
	}
	if len(args) >= 2 {
		shellName = args[1]
		args = args[2:]
	}

	shell := DetectShell(shellName)

	if shell == nil {
		return fmt.Errorf("unknown target shell '%s'", shellName)
	}

	times := NewFileTimes()

	watchString, ok := env[DIRENV_WATCHES]
	if ok {
		err = times.Unmarshal(watchString)
		if err != nil {
			return
		}
	}

	for _, path := range args {
		err = times.Update(path)
		if err != nil {
			return
		}
	}

	e := make(ShellExport)
	e.Add(DIRENV_WATCHES, times.Marshal())

	os.Stdout.WriteString(shell.Export(e))

	return
}

// cmdWatchDir is `direnv watch-dir SHELL DIR`
var cmdWatchDir = &Cmd{
	Name:    "watch-dir",
	Desc:    "Recursively adds a directory to the list that direnv watches for changes",
	Args:    []string{"SHELL", "DIR"},
	Private: true,
	Action:  actionSimple(cmdWatchDirAction),
}

func cmdWatchDirAction(env Env, args []string) (err error) {
	if len(args) < 3 {
		return fmt.Errorf("a directory is required to add to the list of watches")
	}

	shellName := args[1]
	dir := args[2]

	shell := DetectShell(shellName)

	if shell == nil {
		return fmt.Errorf("unknown target shell '%s'", shellName)
	}

	if _, err := os.Stat(dir); os.IsNotExist(err) {
		return fmt.Errorf("dir '%s' does not exist", dir)
	}

	times := NewFileTimes()

	watchString, ok := env[DIRENV_WATCHES]
	if ok {
		err = times.Unmarshal(watchString)
		if err != nil {
			return
		}
	}

	err = filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		return times.Update(path)
	})
	if err != nil {
		return err
	}

	e := make(ShellExport)
	e.Add(DIRENV_WATCHES, times.Marshal())

	os.Stdout.WriteString(shell.Export(e))

	return
}

// cmdWatchList is `direnv watch-list SHELL`
var cmdWatchList = &Cmd{
	Name:    "watch-list",
	Desc:    "Pipe pairs of `mtime path` to stdin to build a list of files to watch.",
	Args:    []string{"[SHELL]"},
	Private: true,
	Action:  actionSimple(cmdWatchListAction),
}

func cmdWatchListAction(env Env, args []string) (err error) {
	var shellName string

	if len(args) >= 2 {
		shellName = args[1]
	} else {
		shellName = "bash"
	}

	shell := DetectShell(shellName)

	if shell == nil {
		return fmt.Errorf("unknown target shell '%s'", shellName)
	}

	times := NewFileTimes()

	watchString, ok := env[DIRENV_WATCHES]
	if ok {
		err = times.Unmarshal(watchString)
		if err != nil {
			return
		}
	}

	// Read `mtime path` lines from stdin
	reader := bufio.NewReader(os.Stdin)

	i := 0
	for {
		i++
		line, err := reader.ReadString('\n')
		if err == io.EOF {
			break
		} else if err != nil {
			return err
		}

		elems := strings.SplitN(line[:len(line)-1], " ", 2)
		if len(elems) != 2 {
			return fmt.Errorf("line %d: expected to contain two elements", i)
		}

		mtime, err := strconv.Atoi(elems[0])
		if err != nil {
			return fmt.Errorf("line %d: %w", i, err)
		}
		path := elems[1]

		// add to watch list
		err = times.NewTime(path, int64(mtime), true)
		if err != nil {
			return err
		}
	}

	e := make(ShellExport)
	e.Add(DIRENV_WATCHES, times.Marshal())

	os.Stdout.WriteString(shell.Export(e))

	return
}

// cmdWatchPrint is `direnv watch-print`
var cmdWatchPrint = &Cmd{
	Name:    "watch-print",
	Desc:    "prints the watched paths",
	Args:    []string{"[--null]"},
	Private: true,
	Action:  actionSimple(cmdWatchPrintAction),
}

func cmdWatchPrintAction(env Env, args []string) (err error) {
	sep := "\n"
	if len(args) > 1 && args[1] == "--null" {
		sep = "\000"
	}

	watchString, ok := env[DIRENV_WATCHES]
	if !ok {
		return nil
	}

	times := NewFileTimes()
	if err = times.Unmarshal(watchString); err != nil {
		return err
	}

	for _, time := range *times.list {
		_, err = os.Stdout.WriteString(time.Path + sep)
		if err != nil {
			return err
		}
	}

	return
}

// cmdCurrent is `direnv current PATH`
var cmdCurrent = &Cmd{
	Name:    "current",
	Desc:    "Reports whether direnv's view of a file is current (or stale)",
	Args:    []string{"PATH"},
	Private: true,
	Action:  actionSimple(cmdCurrentAction),
}

func cmdCurrentAction(env Env, args []string) (err error) {
	if len(args) < 2 {
		err = fmt.Errorf("missing PATH argument")
		return
	}

	path := args[1]
	watches := NewFileTimes()
	watchString, ok := env[DIRENV_WATCHES]
	if ok {
		err = watches.Unmarshal(watchString)
		if err != nil {
			return
		}
	}

	err = watches.CheckOne(path)

	return
}
