		sep = "\000"
	}

	watchString, ok := env[DIRENV_WATCHES]
	if !ok {
		return nil
	}

	times := NewFileTimes()
	if err = times.Unmarshal(watchString); err != nil {
		return err
	}

	for _, time := range *times.list {
		_, err = os.Stdout.WriteString(time.Path + sep)
		if err != nil {
			return err
		}
	}

	return
}

// cmdCurrent is `direnv current PATH`
