		if hashErr != nil || currentHash != hash {
			_ = os.Remove(filename)
			continue
		}

		if pHash, err := pathHash(envrcStr); err == nil {
			validRequired[pHash] = envrcStr
		}
	}

	pruneRequired(config.AllowedRequiredDir(), validRequired)

	return nil
}

