	Private: true,
	Action:  actionWithConfig(cmdCheckRequiredAction),
}

func cmdCheckRequiredAction(_ Env, args []string, config *Config) (err error) {
	if len(args) < 2 {
		return fmt.Errorf("a shell name is required")
	}
	if len(args) < 3 {
		return fmt.Errorf("an envrc path is required")
	}
	if len(args) < 4 {
		return fmt.Errorf("at least one file path is required")
	}

	shellName := args[1]
	shell := DetectShell(shellName)
	if shell == nil {
		return fmt.Errorf("unknown target shell '%s'", shellName)
	}

	envrcPath, err := filepath.Abs(args[2])
	if err != nil {
		return err
	}

	envrcHash, err := pathHash(envrcPath)
	if err != nil {
		return err
	}
	requiredDir := filepath.Join(config.AllowedRequiredDir(), envrcHash)
	rcDir := filepath.Dir(envrcPath)

	var unapproved []string
	for _, rel := range args[3:] {
		if filepath.IsAbs(rel) {
			fmt.Print(requiredFailure(fmt.Sprintf("require_allowed: path must be relative: %s", rel)))
			return nil
		}
		if strings.Contains(rel, "..") {
			fmt.Print(requiredFailure(fmt.Sprintf("require_allowed: path must not contain '..': %s", rel)))
			return nil
		}

		hash, err := fileHash(filepath.Join(rcDir, rel))
		if err != nil {
			unapproved = append(unapproved, rel)
			continue
		}
		if _, err := os.Stat(filepath.Join(requiredDir, hash)); err != nil {
			unapproved = append(unapproved, rel)
		}
	}

	if len(unapproved) == 0 {
		return nil
	}

	var msg string
	if len(unapproved) == 1 {
		msg = fmt.Sprintf("%s requires approval. Run 'direnv allow' to approve.", unapproved[0])
	} else {
		msg = fmt.Sprintf("%s require approval. Run 'direnv allow' to approve.", strings.Join(unapproved, " and "))
	}

	e := make(ShellExport)
	e.Add(DIRENV_REQUIRED, strings.Join(unapproved, ":"))

	fmt.Print(shell.Export(e) + "log_error " + BashEscape(msg) + ";\nexit 0;\n")
	return nil
}

func requiredFailure(msg string) string {
	return "log_error " + BashEscape(msg) + ";\nexit 1;\n"
}
