package cmd

import (
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"hash"
	"io"
	"strings"
)

// sriAlgo is the hashing algorithm of a SRI hash
type sriAlgo string

const (
	sriSHA256 sriAlgo = "sha256"
	sriSHA384 sriAlgo = "sha384"
	sriSHA512 sriAlgo = "sha512"
)

// sriHash represents a parsed SRI hash
type sriHash struct {
	algo   sriAlgo
	digest []byte
}

// sriParse parses an SRI hash string
func sriParse(str string) (*sriHash, error) {
	idx := strings.IndexByte(str, '-')
	if idx < 0 {
		return nil, fmt.Errorf("sri: not a hash %s", str)
	}

	algo := sriAlgo(str[:idx])
	switch algo {
	case sriSHA256, sriSHA384, sriSHA512:
	default:
		return nil, fmt.Errorf("sri: unsupported algo %s", algo)
	}

	// Support path-safe encoding of the hash
	b64 := strings.ReplaceAll(str[idx+1:], "_", "/")

	digest, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		return nil, err
	}

	return &sriHash{algo, digest}, nil
}

// String returns the SRI representation of the hash
func (h *sriHash) String() string {
	return string(h.algo) + "-" + base64.StdEncoding.EncodeToString(h.digest)
}

// Hex returns the hex representation of the digest
func (h *sriHash) Hex() string {
	return hex.EncodeToString(h.digest)
}

// equal compares two hashes
func (h *sriHash) equal(other *sriHash) bool {
	return h.String() == other.String()
}

// sriWriter computes the SRI hash of the data written through it
type sriWriter struct {
	w    io.Writer
	h    hash.Hash
	algo sriAlgo
}

func newSRIWriter(w io.Writer, algo sriAlgo) *sriWriter {
	var h hash.Hash
	switch algo {
	case sriSHA384:
		h = sha512.New384()
	case sriSHA512:
		h = sha512.New()
	default:
		h = sha256.New()
	}
	return &sriWriter{w, h, algo}
}

func (sw *sriWriter) Write(p []byte) (int, error) {
	n, err := sw.w.Write(p)
	sw.h.Write(p[:n])
	return n, err
}

func (sw *sriWriter) Sum() *sriHash {
	return &sriHash{sw.algo, sw.h.Sum(nil)}
}
