package cmd

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"syscall"
	"unsafe"
)

// cmdFetchURL is `direnv fetchurl <url> [<integrity-hash>]`
var cmdFetchURL = &Cmd{
	Name:   "fetchurl",
	Desc:   "Fetches a given URL into direnv's CAS",
	Args:   []string{"<url>", "[<integrity-hash>]"},
	Action: actionWithConfig(cmdFetchURLAction),
}

func casDir(c *Config) string {
	return filepath.Join(c.CacheDir, "cas")
}

func casPath(dir string, h *sriHash) string {
	return filepath.Join(dir, h.Hex())
}

func cmdFetchURLAction(_ Env, args []string, config *Config) (err error) {
	if len(args) < 2 {
		return fmt.Errorf("missing URL argument")
	}

	var (
		integrityHash string
		expectedHash  *sriHash
		url           = args[1]
	)

	if len(args) > 2 {
		integrityHash = args[2]
	}

	cas := casDir(config)

	// Validate the SRI hash if it exists
	if integrityHash != "" {
		expectedHash, err = sriParse(integrityHash)
		if err != nil {
			return err
		}

		// Shortcut if the cache already has the file
		casFile := casPath(cas, expectedHash)
		if fileExists(casFile) {
			fmt.Println(casFile)
			return nil
		}
	}

	// Create the CAS directory if it doesn't exist
	if err = os.MkdirAll(cas, os.FileMode(0755)); err != nil {
		return err
	}

	// Create a temporary file to copy the content into, before the CAS file
	// location can be calculated.
	tmpFile, err := os.CreateTemp(cas, "tmp")
	if err != nil {
		return err
	}
	defer func() {
		if cerr := tmpFile.Close(); cerr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to close temp file: %v\n", cerr)
		}
		if rerr := os.Remove(tmpFile.Name()); rerr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to remove temp file %s: %v\n", tmpFile.Name(), rerr)
		}
	}()

	// Get the URL
	// #nosec G107
	resp, err := http.Get(url)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	// Abort if we don't get a 200 back
	if resp.StatusCode != 200 {
		return fmt.Errorf("expected status code 200 but got %d", resp.StatusCode)
	}

	// While copying the content into the temporary location, also calculate the
	// SRI hash.
	w := newSRIWriter(tmpFile, sriSHA256)
	if _, err = io.Copy(w, resp.Body); err != nil {
		return err
	}

	// Here is the new SRI hash
	calculatedHash := w.Sum()

	// Make the file read-only and executable for later
	if err = os.Chmod(tmpFile.Name(), os.FileMode(0500)); err != nil {
		return err
	}

	// Validate if a comparison hash was given
	if expectedHash != nil && !expectedHash.equal(calculatedHash) {
		return fmt.Errorf("hash mismatch. Expected '%s' but got '%s'", expectedHash, calculatedHash)
	}

	// Derive the CAS file location from the SRI hash
	casFile := casPath(cas, calculatedHash)

	// Put the file into the CAS store
	if err = tmpFile.Close(); err != nil {
		return err
	}
	if err = os.Rename(tmpFile.Name(), casFile); err != nil {
		return err
	}

	// We're done!
	if integrityHash == "" {
		if isTerminal(os.Stdout) {
			fmt.Println("Found hash:", calculatedHash)
			fmt.Println()
			fmt.Println("Invoke fetchurl again with the hash as an argument to get the disk location:")
			fmt.Println()
			fmt.Printf("  direnv fetchurl %q %q\n", url, calculatedHash)
			fmt.Printf("  #=> %s\n", casFile)
		} else {
			fmt.Println(calculatedHash)
		}
	} else {
		fmt.Println(casFile)
	}

	return nil
}

func isTerminal(f *os.File) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}
