package cmd

// A small TOML parser and decoder tailored for the direnv configuration
// file. The error messages try to be informative and to follow the usual
// "toml: line N (last key "K"): message" format.

import (
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

type tomlParseError struct {
	line    int
	lastKey string
	msg     string
}

func (e tomlParseError) Error() string {
	if e.lastKey == "" {
		return fmt.Sprintf("toml: line %d: %s", e.line, e.msg)
	}
	return fmt.Sprintf("toml: line %d (last key %q): %s", e.line, e.lastKey, e.msg)
}

// tomlLocalDatetime and friends represent the TOML date/time values
type tomlDatetime struct {
	t    time.Time
	text string
}

type tomlTableMeta struct {
	implicit bool
	inline   bool
	isArray  bool // array of tables
}

type tomlParser struct {
	src        string
	pos        int
	line       int
	context    []string
	currentKey string

	root     map[string]interface{}
	meta     map[string]*tomlTableMeta
	keyLines map[string]int
}

const tomlEOF = rune(0)

func tomlDecodeFile(path string, v *tomlConfig) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	root, keyLines, err := tomlParse(string(data))
	if err != nil {
		return err
	}
	return tomlDecodeConfig(root, keyLines, v)
}

func tomlParse(src string) (root map[string]interface{}, keyLines map[string]int, err error) {
	p := &tomlParser{
		src:      src,
		line:     1,
		root:     make(map[string]interface{}),
		meta:     make(map[string]*tomlTableMeta),
		keyLines: make(map[string]int),
	}
	defer func() {
		if r := recover(); r != nil {
			if pe, ok := r.(tomlParseError); ok {
				err = pe
				return
			}
			panic(r)
		}
	}()

	// Validate UTF-8 upfront
	line := 1
	for i := 0; i < len(src); {
		r, size := utf8.DecodeRuneInString(src[i:])
		if r == utf8.RuneError && size == 1 {
			panic(tomlParseError{line: line, msg: fmt.Sprintf("invalid UTF-8 byte: 0x%02x", src[i])})
		}
		if r == '\n' {
			line++
		}
		i += size
	}

	p.parseTopLevel()
	return p.root, p.keyLines, nil
}

// --- low level cursor

func (p *tomlParser) peek() rune {
	if p.pos >= len(p.src) {
		return tomlEOF
	}
	r, _ := utf8.DecodeRuneInString(p.src[p.pos:])
	return r
}

func (p *tomlParser) peekN(n int) string {
	end := p.pos + n
	if end > len(p.src) {
		end = len(p.src)
	}
	return p.src[p.pos:end]
}

func (p *tomlParser) atEOF() bool {
	return p.pos >= len(p.src)
}

func (p *tomlParser) next() rune {
	if p.pos >= len(p.src) {
		return tomlEOF
	}
	r, size := utf8.DecodeRuneInString(p.src[p.pos:])
	p.pos += size
	if r == '\n' {
		p.line++
	}
	return r
}

func (p *tomlParser) eofLine() int {
	src := p.src
	if strings.HasSuffix(src, "\n") {
		src = src[:len(src)-1]
	}
	return 1 + strings.Count(src, "\n")
}

func (p *tomlParser) current() string {
	ctx := strings.Join(p.context, ".")
	if p.currentKey == "" {
		return ctx
	}
	if ctx == "" {
		return p.currentKey
	}
	return ctx + "." + p.currentKey
}

func (p *tomlParser) errorf(format string, a ...interface{}) {
	panic(tomlParseError{line: p.line, lastKey: p.current(), msg: fmt.Sprintf(format, a...)})
}

func (p *tomlParser) errorAtLine(line int, format string, a ...interface{}) {
	panic(tomlParseError{line: line, lastKey: p.current(), msg: fmt.Sprintf(format, a...)})
}

func (p *tomlParser) eofErrorf(format string, a ...interface{}) {
	p.errorAtLine(p.eofLine(), format, a...)
}

func isTomlWhitespace(r rune) bool {
	return r == ' ' || r == '\t'
}

func isTomlNL(r rune) bool {
	return r == '\n' || r == '\r'
}

func isBareKeyChar(r rune) bool {
	return (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '_' || r == '-'
}

func (p *tomlParser) skipWhitespace() {
	for isTomlWhitespace(p.peek()) {
		p.next()
	}
}

func (p *tomlParser) skipComment() {
	if p.peek() != '#' {
		return
	}
	for !p.atEOF() && p.peek() != '\n' {
		r := p.peek()
		if r == '\r' && p.peekN(2) == "\r\n" {
			break
		}
		p.next()
	}
}

// --- top level

func (p *tomlParser) parseTopLevel() {
	for {
		p.skipWhitespace()
		r := p.peek()
		switch {
		case p.atEOF():
			return
		case r == '#':
			p.skipComment()
			continue
		case r == '\n':
			p.next()
			continue
		case r == '\r':
			if p.peekN(2) == "\r\n" {
				p.next()
				p.next()
				continue
			}
			p.next()
			p.errorf("expected '.' or '=', but got %q instead", r)
		case r == '[':
			p.next()
			if p.peek() == '[' {
				p.next()
				p.parseArrayTableHeader()
			} else {
				p.parseTableHeader()
			}
		default:
			p.parseKeyValue(p.root, p.context, false)
		}
		p.expectEndOfItem()
	}
}

func (p *tomlParser) expectEndOfItem() {
	p.skipWhitespace()
	r := p.peek()
	switch {
	case p.atEOF():
		return
	case r == '#':
		p.skipComment()
		return
	case r == '\n':
		return
	case r == '\r' && p.peekN(2) == "\r\n":
		return
	}
	p.errorf("expected a top-level item to end with a newline, comment, or EOF, but got %q instead", r)
}

// --- keys

// parseKey parses a dotted key, ending with the given terminator.
func (p *tomlParser) parseKey(inTableName bool) []string {
	var parts []string
	for {
		p.skipWhitespace()
		r := p.peek()
		switch {
		case p.atEOF():
			if inTableName {
				p.eofErrorf("unexpected EOF; expected '.' or ']' to end table name")
			}
			p.eofErrorf("unexpected EOF; expected key separator '='")
		case r == '"':
			p.next()
			parts = append(parts, p.parseBasicString(false))
		case r == '\'':
			p.next()
			parts = append(parts, p.parseLiteralString(false))
		case isBareKeyChar(r):
			start := p.pos
			for isBareKeyChar(p.peek()) {
				p.next()
			}
			parts = append(parts, p.src[start:p.pos])
		case inTableName && r == ']':
			p.next()
			p.errorf("unexpected end of table name (table names cannot be empty)")
		case inTableName && r == '.':
			p.next()
			p.errorf("unexpected table separator (table names cannot be empty)")
		case r == '=':
			p.next()
			if len(parts) == 0 {
				p.errorf("unexpected '=': key name appears blank")
			}
			p.errorf("unexpected '='")
		case r == '.':
			p.next()
			if len(parts) == 0 {
				p.errorf("unexpected '.': keys cannot start with a '.'")
			}
			p.errorf("unexpected '.'")
		default:
			if inTableName {
				p.next()
				p.errorf("expected '.' or ']' to end table name, but got %q instead", r)
			}
			p.errorf("expected '.' or '=', but got %q instead", r)
		}

		// after a key part
		p.skipWhitespace()
		r = p.peek()
		switch {
		case r == '.':
			p.next()
			continue
		case p.atEOF():
			if inTableName {
				p.eofErrorf("unexpected EOF; expected '.' or ']' to end table name")
			}
			p.eofErrorf("unexpected EOF; expected key separator '='")
		case inTableName && r == ']':
			return parts
		case !inTableName && r == '=':
			return parts
		default:
			if inTableName {
				p.next()
				p.errorf("expected '.' or ']' to end table name, but got %q instead", r)
			}
			p.errorf("expected '.' or '=', but got %q instead", r)
		}
	}
}

func joinKey(parts []string) string {
	return strings.Join(parts, ".")
}

// --- tables

func (p *tomlParser) parseTableHeader() {
	line := p.line
	key := p.parseKey(true)
	p.next() // ]

	p.context = nil
	p.currentKey = ""

	table := p.root
	for i, part := range key {
		path := joinKey(key[:i+1])
		existing, ok := table[part]
		last := i == len(key)-1
		if !ok {
			newTable := make(map[string]interface{})
			table[part] = newTable
			p.meta[path] = &tomlTableMeta{implicit: !last}
			p.keyLines[path] = line
			table = newTable
		} else {
			switch v := existing.(type) {
			case map[string]interface{}:
				m := p.meta[path]
				if last {
					if m != nil && m.implicit {
						m.implicit = false
					} else {
						p.errorAtLine(line, "Key '%s' has already been defined.", path)
					}
				} else if m != nil && m.inline {
					p.errorAtLine(line, "Key '%s' has already been defined.", path)
				}
				table = v
			case []map[string]interface{}:
				if last {
					p.errorAtLine(line, "Key '%s' has already been defined.", path)
				}
				table = v[len(v)-1]
			default:
				p.errorAtLine(line, "Key '%s' has already been defined.", path)
			}
		}
		if !last {
			p.context = append(p.context, part)
		}
	}
	p.context = key
}

func (p *tomlParser) parseArrayTableHeader() {
	line := p.line
	key := p.parseKey(true)
	p.next() // ]
	if p.peek() != ']' {
		r := p.next()
		if r == tomlEOF {
			p.eofErrorf("unexpected EOF; expected end of table array name delimiter ']'")
		}
		p.errorf("expected end of table array name delimiter ']', but got %q instead", r)
	}
	p.next()

	p.context = nil
	p.currentKey = ""

	table := p.root
	for i, part := range key {
		path := joinKey(key[:i+1])
		existing, ok := table[part]
		last := i == len(key)-1
		if last {
			newTable := make(map[string]interface{})
			if !ok {
				table[part] = []map[string]interface{}{newTable}
				p.meta[path] = &tomlTableMeta{isArray: true}
				p.keyLines[path] = line
			} else {
				arr, isArr := existing.([]map[string]interface{})
				if !isArr {
					p.errorAtLine(line, "Key '%s' was already created and cannot be used as an array.", path)
				}
				table[part] = append(arr, newTable)
			}
			table = newTable
		} else {
			if !ok {
				newTable := make(map[string]interface{})
				table[part] = newTable
				p.meta[path] = &tomlTableMeta{implicit: true}
				p.keyLines[path] = line
				table = newTable
			} else {
				switch v := existing.(type) {
				case map[string]interface{}:
					table = v
				case []map[string]interface{}:
					table = v[len(v)-1]
				default:
					p.errorAtLine(line, "Key '%s' has already been defined.", path)
				}
			}
			p.context = append(p.context, part)
		}
	}
	p.context = key
}

// --- key/values

func (p *tomlParser) parseKeyValue(table map[string]interface{}, ctx []string, inline bool) {
	line := p.line
	key := p.parseKey(false)
	p.next() // =

	p.currentKey = joinKey(key)

	value := p.parseValue()

	// navigate the dotted key
	t := table
	for i, part := range key[:len(key)-1] {
		path := joinKey(append(append([]string{}, ctx...), key[:i+1]...))
		existing, ok := t[part]
		if !ok {
			newTable := make(map[string]interface{})
			t[part] = newTable
			p.meta[path] = &tomlTableMeta{implicit: true}
			p.keyLines[path] = line
			t = newTable
			continue
		}
		switch v := existing.(type) {
		case map[string]interface{}:
			t = v
		default:
			p.errorAtLine(line, "Key '%s' has already been defined.", path)
		}
	}

	last := key[len(key)-1]
	path := joinKey(append(append([]string{}, ctx...), key...))
	if _, ok := t[last]; ok {
		if m := p.meta[path]; m != nil && m.implicit {
			m.implicit = false
			p.currentKey = ""
			return
		}
		p.errorAtLine(line, "Key '%s' has already been defined.", path)
	}
	t[last] = value
	p.keyLines[path] = line
	if _, isTable := value.(map[string]interface{}); isTable {
		p.meta[path] = &tomlTableMeta{inline: true}
	}
	if !inline {
		p.currentKey = ""
	}
}

// --- values

func (p *tomlParser) parseValue() interface{} {
	p.skipWhitespace()
	r := p.peek()
	switch {
	case p.atEOF():
		p.eofErrorf("unexpected EOF; expected value")
	case r == '\n' || r == '\r':
		p.errorf("expected value but found %q instead", r)
	case r == '"':
		p.next()
		if p.peekN(2) == `""` {
			p.next()
			p.next()
			return p.parseMultilineBasicString()
		}
		return p.parseBasicString(true)
	case r == '\'':
		p.next()
		if p.peekN(2) == `''` {
			p.next()
			p.next()
			return p.parseMultilineLiteralString()
		}
		return p.parseLiteralString(true)
	case r == '[':
		p.next()
		return p.parseArray()
	case r == '{':
		p.next()
		return p.parseInlineTable()
	case r == '+' || r == '-':
		return p.parseNumberOrDate()
	case r >= '0' && r <= '9':
		return p.parseNumberOrDate()
	case r == '.':
		p.next()
		p.errorf("floats must start with a digit, not '.'")
	case isBareKeyChar(r) && r != '_' && r != '-':
		start := p.pos
		for isBareKeyChar(p.peek()) {
			p.next()
		}
		word := p.src[start:p.pos]
		switch word {
		case "true":
			return true
		case "false":
			return false
		case "inf":
			return math.Inf(1)
		case "nan":
			return math.NaN()
		}
		p.errorf("expected value but found %q instead", word)
	}
	p.errorf("expected value but found %q instead", r)
	return nil
}

func (p *tomlParser) parseBasicString(isValue bool) string {
	var sb strings.Builder
	for {
		r := p.peek()
		switch {
		case p.atEOF():
			p.eofErrorf(`unexpected EOF; expected '"'`)
		case r == '\n' || (r == '\r' && p.peekN(2) == "\r\n"):
			p.errorf("strings cannot contain newlines")
		case r == '"':
			p.next()
			return sb.String()
		case r == '\\':
			p.next()
			sb.WriteString(p.parseEscape())
		default:
			if isControl(r) {
				p.next()
				p.errorf("control characters are not allowed inside strings: '0x%02x'", r)
			}
			p.next()
			sb.WriteRune(r)
		}
	}
}

func isControl(r rune) bool {
	return (r <= 0x08) || (r >= 0x0a && r <= 0x1f) || r == 0x7f
}

func (p *tomlParser) parseEscape() string {
	r := p.next()
	switch r {
	case 'b':
		return "\b"
	case 't':
		return "\t"
	case 'n':
		return "\n"
	case 'f':
		return "\f"
	case 'r':
		return "\r"
	case 'e':
		return "\x1b"
	case '"':
		return "\""
	case '\\':
		return "\\"
	case 'u':
		return p.parseUnicodeEscape(4, "u")
	case 'U':
		return p.parseUnicodeEscape(8, "U")
	case tomlEOF:
		p.eofErrorf(`unexpected EOF; expected '"'`)
	}
	p.errorf("invalid escape in string '\\%c'", r)
	return ""
}

func (p *tomlParser) parseUnicodeEscape(n int, letter string) string {
	start := p.pos
	for i := 0; i < n; i++ {
		r := p.peek()
		if !isHexDigit(r) {
			got := p.src[start:min(len(p.src), start+n)]
			if letter == "u" {
				p.errorf("expected four hexadecimal digits after '\\u', but got %q instead", "\\u"+got)
			}
			p.errorf("expected eight hexadecimal digits after '\\U', but got %q instead", "\\U"+got)
		}
		p.next()
	}
	code, _ := strconv.ParseUint(p.src[start:p.pos], 16, 32)
	if !utf8.ValidRune(rune(code)) {
		p.errorf("Escaped character '\\%s%s' is not valid UTF-8.", letter, p.src[start:p.pos])
	}
	return string(rune(code))
}

func isHexDigit(r rune) bool {
	return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F')
}

func (p *tomlParser) parseLiteralString(isValue bool) string {
	start := p.pos
	for {
		r := p.peek()
		switch {
		case p.atEOF():
			p.eofErrorf(`unexpected EOF; expected "'"`)
		case r == '\n' || (r == '\r' && p.peekN(2) == "\r\n"):
			p.errorf("strings cannot contain newlines")
		case r == '\'':
			s := p.src[start:p.pos]
			p.next()
			return s
		default:
			if isControl(r) && r != '\t' {
				p.next()
				p.errorf("control characters are not allowed inside strings: '0x%02x'", r)
			}
			p.next()
		}
	}
}

func (p *tomlParser) parseMultilineBasicString() string {
	var sb strings.Builder
	// A newline immediately following the opening delimiter is trimmed
	if p.peek() == '\n' {
		p.next()
	} else if p.peekN(2) == "\r\n" {
		p.next()
		p.next()
	}
	for {
		r := p.peek()
		switch {
		case p.atEOF():
			p.eofErrorf(`unexpected EOF; expected '"""'`)
		case r == '"' && p.peekN(3) == `"""`:
			p.next()
			p.next()
			p.next()
			// up to two additional quotes are allowed
			for i := 0; i < 2 && p.peek() == '"'; i++ {
				p.next()
				sb.WriteByte('"')
			}
			return sb.String()
		case r == '\\':
			p.next()
			// line ending backslash
			save := p.pos
			saveLine := p.line
			for isTomlWhitespace(p.peek()) {
				p.next()
			}
			if p.peek() == '\n' || p.peekN(2) == "\r\n" {
				for isTomlWhitespace(p.peek()) || p.peek() == '\n' || p.peek() == '\r' {
					p.next()
				}
				continue
			}
			p.pos = save
			p.line = saveLine
			sb.WriteString(p.parseEscape())
		default:
			p.next()
			if r == '\r' && p.peek() == '\n' {
				p.next()
				sb.WriteString("\r\n")
				continue
			}
			sb.WriteRune(r)
		}
	}
}

func (p *tomlParser) parseMultilineLiteralString() string {
	if p.peek() == '\n' {
		p.next()
	} else if p.peekN(2) == "\r\n" {
		p.next()
		p.next()
	}
	start := p.pos
	for {
		r := p.peek()
		switch {
		case p.atEOF():
			p.eofErrorf(`unexpected EOF; expected "'''"`)
		case r == '\'' && p.peekN(3) == "'''":
			end := p.pos
			p.next()
			p.next()
			p.next()
			for i := 0; i < 2 && p.peek() == '\''; i++ {
				p.next()
				end++
			}
			return p.src[start:end]
		default:
			p.next()
		}
	}
}

func (p *tomlParser) skipWhitespaceNewlinesComments() {
	for {
		r := p.peek()
		switch {
		case isTomlWhitespace(r) || r == '\n':
			p.next()
		case r == '\r' && p.peekN(2) == "\r\n":
			p.next()
			p.next()
		case r == '#':
			p.skipComment()
		default:
			return
		}
	}
}

func (p *tomlParser) parseArray() interface{} {
	arr := make([]interface{}, 0)
	for {
		p.skipWhitespaceNewlinesComments()
		r := p.peek()
		switch {
		case p.atEOF():
			p.eofErrorf("unexpected EOF; expected value")
		case r == ']':
			p.next()
			return arr
		case r == ',':
			p.next()
			p.errorf("unexpected comma")
		}
		arr = append(arr, p.parseValue())
		p.skipWhitespaceNewlinesComments()
		r = p.peek()
		switch {
		case r == ',':
			p.next()
		case r == ']':
			p.next()
			return arr
		case p.atEOF():
			p.eofErrorf("expected a comma (',') or array terminator (']'), but got end of file")
		default:
			p.next()
			p.errorf("expected a comma (',') or array terminator (']'), but got %q", r)
		}
	}
}

func (p *tomlParser) parseInlineTable() interface{} {
	table := make(map[string]interface{})
	savedContext := p.context
	savedKey := p.currentKey
	p.context = append(append([]string{}, p.context...), strings.Split(p.currentKey, ".")...)
	p.currentKey = ""

	first := true
	for {
		p.skipWhitespace()
		r := p.peek()
		switch {
		case p.atEOF():
			p.eofErrorf("expected a comma or an inline table terminator '}', but got end of file instead")
		case r == '\n' || r == '\r':
			p.errorf("newlines not allowed within inline tables")
		case r == '}':
			if !first {
				p.errorf("trailing comma not allowed in inline tables")
			}
			p.next()
			p.context = savedContext
			p.currentKey = savedKey
			return table
		case r == ',':
			p.errorf("unexpected comma")
		}
		first = false
		p.parseKeyValue(table, p.context, true)
		p.skipWhitespace()
		r = p.peek()
		switch {
		case r == ',':
			p.next()
			p.skipWhitespace()
			if p.peek() == '}' {
				p.errorf("trailing comma not allowed in inline tables")
			}
		case r == '}':
			p.next()
			p.context = savedContext
			p.currentKey = savedKey
			return table
		case p.atEOF():
			p.eofErrorf("expected a comma or an inline table terminator '}', but got end of file instead")
		case r == '\n' || r == '\r':
			p.errorf("newlines not allowed within inline tables")
		default:
			p.errorf("expected a comma or an inline table terminator '}', but got %q instead", r)
		}
		p.currentKey = ""
	}
}

func isNumberChar(r rune) bool {
	return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
		r == '_' || r == '.' || r == '+' || r == '-' || r == ':'
}

func (p *tomlParser) parseNumberOrDate() interface{} {
	start := p.pos
	r := p.peek()
	if r == '+' || r == '-' {
		p.next()
		n := p.peek()
		if !(n >= '0' && n <= '9') && n != 'i' && n != 'n' {
			if n == '\n' {
				p.next()
			}
			p.errorf("expected a digit but got %q", n)
		}
	}

	// Scan the token
	for {
		c := p.peek()
		if isNumberChar(c) {
			p.next()
			continue
		}
		// Datetimes may contain a space between the date and the time
		if c == ' ' && p.looksLikeDateTimeSpace(start) {
			p.next()
			continue
		}
		break
	}
	tok := p.src[start:p.pos]

	// Rewind to the longest valid prefix for numbers in bases
	if v, ok := p.tryDatetime(tok); ok {
		return v
	}
	if strings.ContainsAny(tok, ":") || (len(tok) >= 5 && tok[4] == '-' && isAllDigits(tok[:4])) {
		p.errorf("invalid datetime: %q", tok)
	}

	return p.parseNumberToken(start, tok)
}

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func (p *tomlParser) looksLikeDateTimeSpace(start int) bool {
	tok := p.src[start:p.pos]
	// YYYY-MM-DD followed by a space and HH:
	if len(tok) == 10 && tok[4] == '-' && tok[7] == '-' {
		rest := p.peekN(4)
		if len(rest) >= 4 && rest[0] == ' ' && rest[1] >= '0' && rest[1] <= '9' && rest[2] >= '0' && rest[2] <= '9' && rest[3] == ':' {
			return true
		}
	}
	return false
}

func (p *tomlParser) tryDatetime(tok string) (interface{}, bool) {
	layouts := []string{
		"2006-01-02T15:04:05.999999999Z07:00",
		"2006-01-02t15:04:05.999999999Z07:00",
		"2006-01-02 15:04:05.999999999Z07:00",
		"2006-01-02T15:04:05.999999999",
		"2006-01-02t15:04:05.999999999",
		"2006-01-02 15:04:05.999999999",
		"2006-01-02",
		"15:04:05.999999999",
	}
	norm := tok
	if strings.HasSuffix(norm, "z") {
		norm = norm[:len(norm)-1] + "Z"
	}
	for _, layout := range layouts {
		if t, err := time.ParseInLocation(layout, norm, time.Local); err == nil {
			return tomlDatetime{t: t, text: tok}, true
		}
	}
	return nil, false
}

func (p *tomlParser) parseNumberToken(start int, tok string) interface{} {
	sign := ""
	body := tok
	if strings.HasPrefix(body, "+") || strings.HasPrefix(body, "-") {
		sign = body[:1]
		body = body[1:]
	}

	switch body {
	case "inf":
		if sign == "-" {
			return math.Inf(-1)
		}
		return math.Inf(1)
	case "nan":
		return math.NaN()
	}

	// Prefixed integers
	if len(body) > 1 && body[0] == '0' && (body[1] == 'x' || body[1] == 'o' || body[1] == 'b') {
		var valid func(rune) bool
		base := 16
		name := "hexadecimal"
		switch body[1] {
		case 'x':
			valid = isHexDigit
		case 'o':
			base = 8
			name = "octal"
			valid = func(r rune) bool { return r >= '0' && r <= '7' }
		case 'b':
			base = 2
			name = "binary"
			valid = func(r rune) bool { return r == '0' || r == '1' }
		}
		// find the longest valid prefix
		i := 2
		for i < len(body) && (valid(rune(body[i])) || body[i] == '_') {
			i++
		}
		digits := body[2:i]
		if digits == "" {
			p.errorf("not a %s number: '%s'", name, tok)
		}
		// rewind the cursor to the end of the valid part
		p.rewindTo(start + len(sign) + i)
		if strings.HasPrefix(digits, "_") || strings.HasSuffix(digits, "_") || strings.Contains(digits, "__") {
			p.errorf("Invalid integer %q: underscores must be surrounded by digits", p.src[start:p.pos])
		}
		n, err := strconv.ParseInt(strings.ReplaceAll(digits, "_", ""), base, 64)
		if err != nil {
			p.errorf("%s is out of range for int64", p.src[start:p.pos])
		}
		return n
	}

	// Decimal numbers: find the longest prefix made of number characters
	i := 0
	for i < len(body) && ((body[i] >= '0' && body[i] <= '9') || body[i] == '_' || body[i] == '.' || body[i] == 'e' || body[i] == 'E' ||
		((body[i] == '+' || body[i] == '-') && i > 0 && (body[i-1] == 'e' || body[i-1] == 'E'))) {
		i++
	}
	p.rewindTo(start + len(sign) + i)
	num := p.src[start:p.pos]
	digits := body[:i]

	if strings.ContainsAny(digits, ".eE") {
		if strings.HasPrefix(digits, ".") {
			p.errorf("floats must start with a digit, not '.'")
		}
		if idx := strings.IndexByte(digits, '.'); idx >= 0 {
			if idx+1 >= len(digits) || digits[idx+1] < '0' || digits[idx+1] > '9' {
				p.errorf("Invalid float %q: '.' must be followed by one or more digits", num)
			}
		}
		if strings.HasPrefix(digits, "_") || strings.HasSuffix(digits, "_") || strings.Contains(digits, "__") {
			p.errorf("Invalid float %q: underscores must be surrounded by digits", num)
		}
		intPart := digits
		if idx := strings.IndexAny(digits, ".eE"); idx >= 0 {
			intPart = digits[:idx]
		}
		if len(intPart) > 1 && intPart[0] == '0' {
			p.errorf("Invalid float %q: cannot have leading zeroes", num)
		}
		f, err := strconv.ParseFloat(sign+strings.ReplaceAll(digits, "_", ""), 64)
		if err != nil {
			p.errorf("Invalid float value: %q", num)
		}
		return f
	}

	if digits == "" {
		p.errorf("expected value but found %q instead", tok)
	}
	if strings.HasPrefix(digits, "_") || strings.HasSuffix(digits, "_") || strings.Contains(digits, "__") {
		p.errorf("Invalid integer %q: underscores must be surrounded by digits", num)
	}
	if len(digits) > 1 && digits[0] == '0' {
		p.errorf("Invalid integer %q: cannot have leading zeroes", num)
	}
	n, err := strconv.ParseInt(sign+strings.ReplaceAll(digits, "_", ""), 10, 64)
	if err != nil {
		p.errorf("%s is out of range for int64", num)
	}
	return n
}

func (p *tomlParser) rewindTo(pos int) {
	for p.pos > pos {
		_, size := utf8.DecodeLastRuneInString(p.src[:p.pos])
		if p.src[p.pos-size] == '\n' {
			p.line--
		}
		p.pos -= size
	}
}

// --- decoding

func tomlTypeName(v interface{}) string {
	switch v.(type) {
	case string:
		return "string"
	case int64:
		return "int64"
	case float64:
		return "float64"
	case bool:
		return "bool"
	case tomlDatetime:
		return "time.Time"
	case []interface{}:
		return "[]any"
	case map[string]interface{}:
		return "map[string]any"
	case []map[string]interface{}:
		return "[]map[string]any"
	}
	return fmt.Sprintf("%T", v)
}

type tomlDecodeError struct {
	line    int
	lastKey string
	msg     string
}

func (e tomlDecodeError) Error() string {
	return tomlParseError{e.line, e.lastKey, e.msg}.Error()
}

func tomlDecodeConfig(root map[string]interface{}, keyLines map[string]int, conf *tomlConfig) error {
	global := &tomlGlobal{}
	conf.tomlGlobal = global
	conf.Global = global

	badType := func(key string, dest string, v interface{}) error {
		return tomlDecodeError{keyLines[key], key, fmt.Sprintf("incompatible types: TOML value has type %s; destination has type %s", tomlTypeName(v), dest)}
	}

	decodeString := func(key string, v interface{}, out *string) error {
		s, ok := v.(string)
		if !ok {
			return badType(key, "string", v)
		}
		*out = s
		return nil
	}

	decodeBool := func(key string, v interface{}, out *bool) error {
		b, ok := v.(bool)
		if !ok {
			return badType(key, "boolean", v)
		}
		*out = b
		return nil
	}

	decodeDuration := func(key string, v interface{}, out **tomlDuration) error {
		var s string
		switch d := v.(type) {
		case string:
			s = d
		case bool:
			s = fmt.Sprintf("%v", d)
		case int64:
			s = fmt.Sprintf("%d", d)
		case float64:
			s = fmt.Sprintf("%f", d)
		case tomlDatetime:
			b, _ := d.t.MarshalText()
			s = string(b)
		default:
			return badType(key, "primitive (string-like)", v)
		}
		d := &tomlDuration{}
		if err := d.UnmarshalText([]byte(s)); err != nil {
			return tomlDecodeError{keyLines[key], key, err.Error()}
		}
		*out = d
		return nil
	}

	decodeStringSlice := func(key string, v interface{}, out *[]string) error {
		arr, ok := v.([]interface{})
		if !ok {
			return badType(key, "slice", v)
		}
		res := make([]string, 0, len(arr))
		for _, elem := range arr {
			s, ok := elem.(string)
			if !ok {
				return badType(key, "string", elem)
			}
			res = append(res, s)
		}
		*out = res
		return nil
	}

	decodeGlobalKey := func(fullKey, key string, v interface{}) (bool, error) {
		switch strings.ToLower(key) {
		case "bash_path":
			return true, decodeString(fullKey, v, &global.BashPath)
		case "disable_stdin":
			return true, decodeBool(fullKey, v, &global.DisableStdin)
		case "strict_env":
			return true, decodeBool(fullKey, v, &global.StrictEnv)
		case "skip_dotenv":
			return true, decodeBool(fullKey, v, &global.SkipDotenv)
		case "load_dotenv":
			return true, decodeBool(fullKey, v, &global.LoadDotenv)
		case "warn_timeout":
			return true, decodeDuration(fullKey, v, &global.WarnTimeout)
		case "hide_env_diff":
			return true, decodeBool(fullKey, v, &global.HideEnvDiff)
		case "log_format":
			return true, decodeString(fullKey, v, &global.LogFormat)
		case "log_filter":
			return true, decodeString(fullKey, v, &global.LogFilter)
		}
		return false, nil
	}

	for key, value := range root {
		switch strings.ToLower(key) {
		case "global":
			table, ok := value.(map[string]interface{})
			if !ok {
				return tomlDecodeError{keyLines[key], key, fmt.Sprintf("type mismatch for cmd.tomlGlobal: expected table but found %s", tomlTypeName(value))}
			}
			for k, v := range table {
				if _, err := decodeGlobalKey(key+"."+k, k, v); err != nil {
					return err
				}
			}
		case "whitelist":
			table, ok := value.(map[string]interface{})
			if !ok {
				return tomlDecodeError{keyLines[key], key, fmt.Sprintf("type mismatch for cmd.tomlWhitelist: expected table but found %s", tomlTypeName(value))}
			}
			for k, v := range table {
				switch strings.ToLower(k) {
				case "prefix":
					if err := decodeStringSlice(key+"."+k, v, &conf.Whitelist.Prefix); err != nil {
						return err
					}
				case "exact":
					if err := decodeStringSlice(key+"."+k, v, &conf.Whitelist.Exact); err != nil {
						return err
					}
				}
			}
		default:
			if _, err := decodeGlobalKey(key, key, value); err != nil {
				return err
			}
		}
	}

	return nil
}
